import {projects,initialState,metrics,totals,eligibility,assign,addQA} from './model.mjs';
const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),pct=n=>n.toFixed(1)+'%';
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=initialState(),page='Overview',filter='all',search='',workerStatus='all',selected='P01',drawer=false;
try{const stored=JSON.parse(localStorage.getItem('fieldops-v1'));if(stored?.version===2&&stored.workers?.length===60&&stored.incidents&&stored.extraQA&&Array.isArray(stored.audit))state=stored;}catch{}
function persist(){try{localStorage.setItem('fieldops-v1',JSON.stringify(state));}catch{toast('Changes apply for this session; browser storage is unavailable.');}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500);}
const icons={Overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',Workforce:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 5a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',Quality:'<path d="M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7Z"/><path d="m8 12 3 3 5-6"/>',Incidents:'<path d="m12 3 10 18H2ZM12 9v5M12 17v1"/>',Scenarios:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',Reports:'<path d="M6 3h9l4 4v14H6ZM14 3v5h5M9 12h7M9 16h7"/>'};
function badge(t,c='green'){return `<span class="badge ${c}"><span class="status-dot"></span>${t}</span>`;}
function overview(){const ms=totals(state),accepted=ms.reduce((n,m)=>n+m.accepted,0),target=ms.reduce((n,m)=>n+m.target,0),active=state.workers.filter(w=>w.status==='Collecting').length,first=ms.reduce((n,m)=>n+m.firstPass,0)/ms.reduce((n,m)=>n+m.firstReviews,0),risk=ms.filter(m=>m.shortfall).length;return `
<div class="banner"><span>◈</span><div><b>Your staffing and delivery picture, in one place.</b> ${risk?`${risk} ${risk===1?'project needs':'projects need'} attention before the 18:00 UTC delivery window.`:'All projects are projected to meet the 18:00 UTC delivery window.'}</div><span class="badge green">4-HOUR HORIZON</span></div>
<div class="kpis"><div class="card kpi"><div class="kpi-label"><span>Active workers</span><span>♧</span></div><div class="kpi-value">${active}<small>/ 60</small></div><div class="kpi-note"><strong>${state.workers.filter(w=>w.status==='Available').length} on reserve</strong> · ${state.workers.filter(w=>w.status==='Offline').length} offline</div></div><div class="card kpi"><div class="kpi-label"><span>Accepted units today</span><span>▧</span></div><div class="kpi-value">${accepted}<small>/ ${target}</small></div><div class="kpi-note"><strong>${pct(accepted/target*100)} delivered</strong> · acceptance-based</div></div><div class="card kpi"><div class="kpi-label"><span>First-pass acceptance</span><span>◇</span></div><div class="kpi-value">${pct(first*100)}</div><div class="kpi-note">${ms.reduce((n,m)=>n+m.firstReviews,0)} completed first reviews</div></div><div class="card kpi"><div class="kpi-label"><span>Projects at risk</span><span>⚑</span></div><div class="kpi-value">${risk}<small>/ 3</small></div><div class="kpi-note"><span style="color:#b18a55">●</span> Forecast below committed delivery</div></div></div>
<div class="grid"><section class="card"><div class="card-head"><div><h2>Delivery performance</h2><p>Accepted units across all projects · simulated history</p></div><div class="legend"><span><i style="background:#76935e"></i>Accepted</span><span><i style="background:#d9dfd1"></i>Target</span></div></div><div class="chart-wrap">${chart()}</div><div class="chart-foot"><span><strong>712 accepted units</strong> in the latest snapshot</span><span>Oct 22 – 28, 2026</span></div></section><section class="card"><div class="card-head"><h2>Delivery watchlist</h2>${badge('Live scenario','gray')}</div>${ms.map(m=>`<div class="risk"><div class="risk-line"><span class="risk-name">${m.name}</span>${badge(m.shortfall?'At risk':'On track',m.shortfall?'amber':'green')}</div><p>${m.client}</p><div class="progress ${m.shortfall?'amber':''}"><span style="width:${Math.min(100,m.forecast/m.target*100)}%"></span></div><div class="risk-bottom"><span>Forecast ${m.forecast} / ${m.target} units</span><button class="text-link" data-project="${m.id}">Investigate ↗</button></div></div>`).join('')}</section></div>
${projectTable(ms)}
<div class="bottom-grid"><section class="card"><div class="card-head"><h2>Operational exceptions</h2><button class="text-link" data-nav="Incidents">View all ↗</button></div>${state.incidents.filter(i=>i.status!=='Resolved').map(i=>`<div class="incident-row"><span class="incident-marker">!</span><div class="incident-copy"><b>${i.title}</b><small>${i.id} · ${projects.find(p=>p.id===i.project).name}</small></div>${badge(i.status,'amber')}</div>`).join('')||'<div class="empty">No open exceptions</div>'}</section><section class="card"><div class="card-head"><h2>Workforce coverage</h2><span class="sub">Assigned vs. required</span></div><div class="capacity">${ms.map(m=>`<div class="capacity-row"><div><span>${m.name}</span><span>${m.active} / 16 agents</span></div><div class="progress"><span style="width:${m.coverage}%"></span></div></div>`).join('')}</div></section></div>`;}
function chart(){const values=[498,565,533,625,589,674,712],targets=[820,860,880,940,960,1000,1040];return `<svg class="chart" viewBox="0 0 650 215" role="img" aria-label="Simulated accepted units by day from October 22 through October 28: 498, 565, 533, 625, 589, 674, 712. Targets: 820, 860, 880, 940, 960, 1000, 1040.">${[0,300,600,900,1200].map(v=>`<line x1="40" x2="640" y1="${183-v*.135}" y2="${183-v*.135}" stroke="#edf0e7" stroke-dasharray="3 4"/><text x="25" y="${187-v*.135}" font-size="9" fill="#a2ac96" text-anchor="end">${v}</text>`).join('')}${values.map((v,i)=>`<rect x="${58+i*82}" y="${183-targets[i]*.135}" width="48" height="${targets[i]*.135}" fill="#e9eddf" rx="4"/><rect x="${58+i*82}" y="${183-v*.135}" width="48" height="${v*.135}" fill="${i===6?'#36593e':'#91a57a'}" rx="4"/><text x="${82+i*82}" y="${174-v*.135}" font-size="9" fill="#748769" text-anchor="middle">${v}</text><text x="${82+i*82}" y="205" font-size="9" fill="#9ca68e" text-anchor="middle">Oct ${22+i}</text>`).join('')}</svg>`;}
function projectTable(ms){return `<section class="card"><div class="card-head"><div><h2>Project portfolio</h2><p>Client commitments and operational health</p></div><select id="project-filter" aria-label="Filter projects"><option value="all">All projects</option>${projects.map(p=>`<option value="${p.id}" ${filter===p.id?'selected':''}>${p.name}</option>`).join('')}</select></div><div class="table-wrap"><table><thead><tr><th>Project / client</th><th>Workers</th><th>Accepted / target</th><th>First-pass QA</th><th>Delivery status</th><th></th></tr></thead><tbody>${ms.filter(m=>filter==='all'||m.id===filter).map(m=>`<tr><td><div class="project-name"><span class="project-icon" style="color:${m.color}">${m.code}</span><div><b>${m.name}</b><small>${m.client}</small></div></div></td><td>${m.active} <span style="color:#9aa48e">/ 16</span></td><td><div class="mini">${m.accepted} <span style="color:#9aa48e">/ ${m.target}</span><div class="progress"><span style="width:${m.accepted/m.target*100}%"></span></div></div></td><td>${pct(m.passRate*100)}</td><td>${badge(m.shortfall?'At risk':'On track',m.shortfall?'amber':'green')}</td><td><button class="text-link" data-project="${m.id}" aria-label="Investigate ${m.name}">View ↗</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function workforce(){const ws=state.workers.filter(w=>(workerStatus==='all'||w.status===workerStatus)&&(`${w.name} ${w.id} ${w.region}`.toLowerCase().includes(search.toLowerCase())));return `<div class="filters"><input id="worker-search" aria-label="Search workers" placeholder="Search name, ID or location…" value="${safe(search)}"><select id="worker-status" aria-label="Worker status"><option value="all">All statuses</option>${['Collecting','Available','Offline','Absent'].map(s=>`<option ${s===workerStatus?'selected':''}>${s}</option>`).join('')}</select><button class="btn primary" data-open="P01">Assign reserve worker ↗</button></div><section class="card"><div class="card-head"><h2>Worker directory</h2><span class="sub">${ws.length} of 60 agents</span></div><div class="table-wrap"><table><thead><tr><th>Agent</th><th>Location</th><th>Assignment</th><th>Status</th><th>Qualified projects</th><th>Capacity / h</th></tr></thead><tbody>${ws.map(w=>`<tr><td><div class="project-name"><span class="avatar">${w.name.split(' ').map(n=>n[0]).join('')}</span><div><b>${w.name}</b><small>${w.id}</small></div></div></td><td>${w.region}</td><td>${projects.find(p=>p.id===w.project)?.name||'Reserve pool'}</td><td>${badge(w.status,w.status==='Collecting'?'green':w.status==='Available'?'gray':'amber')}</td><td>${[...new Set(w.qualified)].join(' · ')}</td><td>${w.units} units</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No agents match these filters.</td></tr>'}</tbody></table></div></section><p class="definition">Availability and qualifications are enforced on assignment. Each assignment covers the same 14:00–18:00 UTC window. Capacity is simulated; no real personnel data is used.</p>`;}
function quality(){return `<div class="grid">${totals(state).map(m=>`<section class="card"><div class="card-head"><div><h2>${m.name}</h2><p>${m.client}</p></div>${badge(m.backlog>15?'Review queue':'Stable',m.backlog>15?'amber':'green')}</div><div class="panel-body"><div class="kpi-value">${pct(m.passRate*100)}<small>first-pass</small></div><div class="metric-row"><span>First-pass accepted / reviewed</span><b>${m.firstPass} / ${m.firstReviews}</b></div><div class="metric-row"><span>Awaiting review</span><b>${m.backlog} units</b></div><div class="metric-row"><span>Review capacity</span><b>${m.qaRate+state.extraQA[m.id]} units / h</b></div><div class="metric-row"><span>First-review failures</span><b>${m.firstReviews-m.firstPass} units</b></div><p class="definition">Failures remain in first-pass history after rework. Forecast assumes the observed acceptance ratio continues. Backlog = submitted − reviewed.</p><button class="btn primary" data-qa="${m.id}" ${state.extraQA[m.id]>=12?'disabled':''}>Add reserve QA · +6 units/h</button><p class="definition">$72 per block for the remaining 4 hours · maximum 2 blocks per project</p></div></section>`).join('')}</div><div class="card"><div class="card-head"><h2>QA methodology</h2></div><div class="panel-body"><p>Only accepted work fulfills a delivery commitment. First-pass acceptance uses completed first reviews as its denominator; awaiting-review units are excluded. Rejected and reworked submissions do not create additional accepted units. No client satisfaction scores are invented.</p></div></div>`;}
function incidents(){return `<section class="card"><div class="card-head"><h2>Incident register</h2><span class="sub">${state.incidents.filter(i=>i.status!=='Resolved').length} open exceptions</span></div>${state.incidents.map(i=>`<div class="panel-body" style="border-top:1px solid var(--line);padding-top:20px"><div class="risk-line"><h3>${i.title}</h3>${badge(i.status,i.status==='Resolved'?'green':'amber')}</div><p>${i.detail}</p><div class="risk-line"><span class="sub">${i.id} · ${projects.find(p=>p.id===i.project).name} · Owner: ${i.owner}</span><button class="btn" data-incident="${i.id}">${i.status==='Open'?'Investigate':i.status==='Investigating'?'Resolve incident':'Reopen incident'}</button></div></div>`).join('')}</section><p class="definition">Incident status is a coordination record. Resolving an incident does not restore device connectivity or alter staffing automatically. Scenario capacity changes are controlled separately.</p>`;}
function scenarios(){const ms=totals(state),bs=totals(initialState()),before=bs.reduce((n,m)=>n+m.forecast,0),after=ms.reduce((n,m)=>n+m.forecast,0);return `<div class="details"><section class="card"><div class="card-head"><div><h2>Scenario workbench</h2><p>Same demand. Explicit interventions. Traceable decisions.</p></div>${badge('Simulation','gray')}</div><div class="panel-body"><div class="scenario-control"><div><b>Home routines · connectivity stress</b><p>Reduce collection capacity by 35%. Existing offline agents remain excluded.</p></div><button class="btn ${state.outage?'primary':''}" id="toggle-outage">${state.outage?'Remove stress':'Apply stress'}</button></div><div class="scenario-control"><div><b>Reallocate qualified reserve staff</b><p>Availability, existing assignment and qualification checked before allocation.</p></div><button class="btn" data-open="P01">Review candidates ↗</button></div><div class="scenario-control"><div><b>Retail interactions · QA reserve</b><p>Add 6 reviews/hour at $72 over the four-hour window.</p></div><button class="btn" data-qa="P02" ${state.extraQA.P02>=12?'disabled':''}>Add QA block</button></div><div class="callout">${ms.find(m=>m.id==='P02').limited==='QA capacity'?'Retail delivery is constrained by QA capacity. More collectors cannot resolve that bottleneck alone.':'Retail review capacity has increased. Inspect the forecast to identify the next constraint.'}</div><button class="btn" id="reset">Reset all demo changes</button><p class="definition">Reset clears assignments, added QA, stress, incident changes, and audit history. This is a deterministic scenario calculation, not a validated prediction model.</p></div></section><section class="card"><div class="card-head"><h2>Baseline vs. current</h2></div><div class="panel-body"><div class="metric-row"><span>Baseline projected accepted units</span><b>${before}</b></div><div class="metric-row"><span>Current projected accepted units</span><b>${after}</b></div><div class="metric-row"><span>Projected output change</span><b>${after-before>=0?'+':''}${after-before} units</b></div><div class="metric-row"><span>Projects at risk</span><b>${bs.filter(m=>m.shortfall).length} → ${ms.filter(m=>m.shortfall).length}</b></div><div class="metric-row"><span>Remaining-window direct cost</span><b>${money(ms.reduce((n,m)=>n+m.cost,0))}</b></div><div class="metric-row"><span>Direct cost change</span><b>${money(ms.reduce((n,m)=>n+m.cost,0)-bs.reduce((n,m)=>n+m.cost,0))}</b></div><p class="definition">Projected accepted = accepted now + min(collection capacity × observed acceptance + eligible backlog, review capacity × observed acceptance). Horizon: 4 hours. Direct cost includes assigned collection labor and incremental QA reserve; existing QA labor and overhead are excluded. This is not profit or realized ROI.</p></div></section></div><section class="card" style="margin-top:24px"><div class="card-head"><h2>Decision audit trail</h2><span class="sub">${state.audit.length} actions</span></div><div class="panel-body">${state.audit.map(a=>`<div class="audit"><small>${new Date(a.time).toLocaleString('en-US',{timeZone:'UTC'})} UTC</small>${safe(a.action)}</div>`).join('')||'<div class="empty">No interventions yet. Apply a scenario or assign a reserve agent to begin.</div>'}</div></section>`;}
function report(){const ms=totals(state);return `<div class="report"><section class="card"><div class="panel-body"><div class="eyebrow">Client operations brief · simulated</div><h2 style="margin-top:14px">Delivery & operational readiness</h2><p class="sub">Snapshot: October 28, 2026, 14:00 UTC · Commitments due at 18:00 UTC</p><p>This report summarizes the current simulated state. ${ms.filter(m=>m.shortfall).length} of 3 client projects are projected below their delivery commitment. Forecasts assume current collection rates and observed QA acceptance continue throughout the remaining four hours.</p>${ms.map(m=>`<div style="border-top:1px solid var(--line);padding-top:20px;margin-top:20px"><div class="risk-line"><h3>${m.client} · ${m.name}</h3>${badge(m.shortfall?'At risk':'On track',m.shortfall?'amber':'green')}</div><ul><li>Accepted delivery: ${m.accepted} of ${m.target} committed units.</li><li>Projected accepted by deadline: ${m.forecast}; projected shortfall: ${m.shortfall}.</li><li>Active collectors: ${m.active}; observed first-pass acceptance: ${pct(m.passRate*100)}.</li><li>Current constraint: ${m.limited.toLowerCase()}; awaiting review: ${m.backlog} units.</li></ul></div>`).join('')}<h3 style="margin-top:24px">Recorded interventions</h3><ul>${state.audit.length?state.audit.map(a=>`<li>${safe(a.action)}</li>`).join(''):'<li>No interventions recorded in this scenario.</li>'}</ul><p class="definition">All workers, clients, costs and operational results are fictional. No real client engagement or achieved business outcome is claimed. Forecast delivery counts accepted units, not uploaded submissions. Browser-local changes are saved on this device only.</p><div class="actions"><button class="btn primary" id="download-report">Download report · CSV ↓</button><button class="btn" id="print-report">Print / save PDF</button></div></div></section></div>`;}
function drawerHTML(){const m=metrics(state,selected),available=state.workers.filter(w=>!eligibility(state,w,selected));return `<div class="modal-bg" id="modal-bg"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><button class="close" id="close-drawer" aria-label="Close project details">×</button><div class="eyebrow">Delivery investigation</div><h2 id="drawer-title" style="margin-top:12px">${m.name}</h2><p class="sub" style="margin-top:8px">${m.client} · Deadline 18:00 UTC</p><label class="sr-only" for="drawer-project">Select project</label><select id="drawer-project">${projects.map(p=>`<option value="${p.id}" ${p.id===selected?'selected':''}>${p.name}</option>`).join('')}</select><div class="metric-row"><span>Projected delivery</span><b>${m.forecast} / ${m.target}</b></div><div class="metric-row"><span>Projected shortfall</span><b>${m.shortfall} units</b></div><div class="metric-row"><span>Current constraint</span><b>${m.limited}</b></div><div class="callout">${m.shortfall?`${m.shortfall} accepted units below commitment. Inspect ${m.limited.toLowerCase()} before allocating reserve capacity.`:'Current capacity is projected to cover the commitment. Additional staffing may increase direct cost without improving on-time fulfillment.'}</div><div class="risk-line"><h3>Qualified reserve workers</h3><span class="sub">${available.length} eligible</span></div><p class="definition">Each candidate is available for the same four-hour window, unassigned and qualified. Assignment cost is hourly rate × 4 hours.</p>${available.map(w=>`<div class="candidate"><div><b>${w.name}</b><small>${w.id} · ${w.region} · ${w.units} units/h</small><small>${money(w.hourly)}/h · ${money(w.hourly*4)} window cost</small></div><button class="btn primary" data-assign="${w.id}">Assign</button></div>`).join('')||'<div class="empty">No eligible reserve agents remain.</div>'}<button class="btn" style="width:100%;margin-top:20px" data-qa="${m.id}" ${state.extraQA[m.id]>=12?'disabled':''}>Add QA reserve · +6 units/h · $72</button><p class="definition">Changes are applied to the simulated current scenario and logged. Historical accepted units and first-pass results stay fixed.</p></section></div>`;}
const subtitles={Overview:'Assign workers, monitor quality, and keep client delivery on track.',Workforce:'The right people, ready for the right work.',Quality:'Accepted work is what counts. Keep the review queue moving.',Incidents:'Make exceptions visible. Give every response an owner.',Scenarios:'Explore operational decisions before the delivery window closes.',Reports:'Turn operational complexity into a clear client update.'};
function render(){const scroll=window.scrollY;$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><i>ƒ</i><span>FieldOps</span></div><div class="workspace">OPERATIONS WORKSPACE</div><nav class="nav" aria-label="Main navigation">${Object.keys(icons).map(n=>`<button data-nav="${n}" class="${page===n?'active':''}" aria-label="${n}" ${page===n?'aria-current="page"':''}><svg viewBox="0 0 24 24">${icons[n]}</svg><span>${n}</span>${n==='Incidents'?`<span class="count">${state.incidents.filter(i=>i.status!=='Resolved').length}</span>`:''}</button>`).join('')}</nav><div class="side-bottom"><div class="simulation-note"><b>◈ &nbsp; Portfolio simulation</b>Fictional teams. Real operational constraints. Explore the decisions.</div><div class="profile"><div class="avatar">OM</div><div><b>Operations manager</b><small>Demo workspace</small></div></div></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span>/ &nbsp; ${page}</span></div><div class="top-right"><span><i class="live-dot"></i>Simulation environment</span><div class="date">▦ &nbsp; Oct 28, 2026 &nbsp; · &nbsp; 14:00 UTC</div><button class="iconbtn" data-nav="Incidents" aria-label="View operational alerts">♧</button></div></header><div class="content"><div class="eyebrow">STAFFING & OPERATIONS / ${page==='Overview'?'DAILY OPERATIONS':page.toUpperCase()}</div><div class="heading"><div><h1>${page==='Overview'?'Operations overview':page==='Quality'?'Quality assurance':page==='Scenarios'?'Scenario planning':page==='Reports'?'Client reporting':page==='Incidents'?'Incidents & escalations':'Workforce management'}</h1><p class="sub">${subtitles[page]}</p></div><div class="actions"><button class="btn" data-nav="Scenarios">◷ &nbsp; Run a scenario</button><button class="btn primary" data-nav="Reports">Export report &nbsp; ↗</button></div></div>${({Overview:overview,Workforce:workforce,Quality:quality,Incidents:incidents,Scenarios:scenarios,Reports:report}[page])()}<footer class="footer"><span>FieldOps &nbsp; / &nbsp; Staffing, quality, and delivery — connected.</span><span>Simulated data · USD · UTC · Saved in this browser</span></footer></div></main>${drawer?drawerHTML():''}`;bind();window.scrollTo(0,scroll);if(drawer)$('#close-drawer').focus();}
function change(action){try{action();persist();render();}catch(e){toast(e.message);}}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;drawer=false;render();window.scrollTo(0,0)});document.querySelectorAll('[data-project],[data-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.project||b.dataset.open;drawer=true;render()});document.querySelectorAll('[data-assign]').forEach(b=>b.onclick=()=>change(()=>{assign(state,b.dataset.assign,selected);toast('Agent assigned. Delivery forecast and cost updated.')}));document.querySelectorAll('[data-qa]').forEach(b=>b.onclick=()=>change(()=>{addQA(state,b.dataset.qa);toast('QA reserve added. Forecast and cost updated.')}));$('#project-filter')?.addEventListener('change',e=>{filter=e.target.value;render()});$('#worker-status')?.addEventListener('change',e=>{workerStatus=e.target.value;render()});$('#worker-search')?.addEventListener('input',e=>{const pos=e.target.selectionStart;search=e.target.value;render();const field=$('#worker-search');field.focus();field.setSelectionRange(pos,pos)});$('#close-drawer')?.addEventListener('click',()=>{drawer=false;render()});$('#modal-bg')?.addEventListener('click',e=>{if(e.target.id==='modal-bg'){drawer=false;render()}});$('#drawer-project')?.addEventListener('change',e=>{selected=e.target.value;render()});$('#toggle-outage')?.addEventListener('click',()=>change(()=>{state.outage=!state.outage;state.audit.unshift({time:new Date().toISOString(),action:`${state.outage?'Applied':'Removed'} 35% connectivity stress to Home routines`})}));$('#reset')?.addEventListener('click',()=>{state=initialState();persist();render();toast('Demo reset to the original baseline.')});document.querySelectorAll('[data-incident]').forEach(b=>b.onclick=()=>change(()=>{const i=state.incidents.find(i=>i.id===b.dataset.incident);i.status=i.status==='Open'?'Investigating':i.status==='Investigating'?'Resolved':'Open';state.audit.unshift({time:new Date().toISOString(),action:`${i.id}: ${i.status} — ${i.title}`});toast('Incident status updated. Capacity is unchanged.')}));$('#print-report')?.addEventListener('click',()=>window.print());$('#download-report')?.addEventListener('click',downloadReport);}
function downloadReport(){const rows=[['FieldOps — SIMULATED operational report'],['Snapshot','2026-10-28 14:00 UTC','Horizon','4 hours'],['Project','Client','Accepted','Target','Projected accepted','Shortfall','Active agents','First-pass acceptance','Awaiting QA','Remaining direct cost USD','Constraint'],...totals(state).map(m=>[m.name,m.client,m.accepted,m.target,m.forecast,m.shortfall,m.active,pct(m.passRate*100),m.backlog,m.cost,m.limited]),[],['Intervention time UTC','Action'],...state.audit.map(a=>[a.time,a.action]),[],['Cost excludes existing QA labor and overhead. All data and projections are simulated.']];const csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='FieldOps-Simulated-Report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Simulated client report downloaded.');}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&drawer){drawer=false;render()}if(e.key==='Tab'&&drawer){const nodes=[...$('.drawer').querySelectorAll('button:not([disabled]),select')];const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});render();
